t.script:
                //
(function () {
    // ── Priority stars ───────────────────────────────────────────────────
    var PRIORITY_LABELS = {0: "Normal", 1: "Low", 2: "High", 3: "Very High"};
    var currentPriority = parseInt(document.getElementById("priority_value").value) || 0;

    function renderStars(val) {
        document.querySelectorAll(".portal-star").forEach(function (s) {
            var sv = parseInt(s.dataset.val);
            s.style.color = sv <= val ? "#f6a623" : "#dee2e6";
        });
        document.getElementById("priority_label").textContent = PRIORITY_LABELS[val] || "Normal";
        document.getElementById("priority_value").value = val;
        currentPriority = val;
    }

    document.querySelectorAll(".portal-star").forEach(function (star) {
        star.addEventListener("click", function () {
            var val = parseInt(this.dataset.val);
            renderStars(val === currentPriority ? 0 : val);
        });
        star.addEventListener("mouseenter", function () {
            var val = parseInt(this.dataset.val);
            document.querySelectorAll(".portal-star").forEach(function (s) {
                s.style.color = parseInt(s.dataset.val) <= val ? "#f6a623" : "#dee2e6";
            });
        });
        star.addEventListener("mouseleave", function () {
            renderStars(currentPriority);
        });
    });

    renderStars(currentPriority);

    // ── JSON-RPC helper ──────────────────────────────────────────────────
    function callJSON(url, params, cb) {
        fetch(url, {
            method: "POST",
            headers: {"Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest"},
            body: JSON.stringify({jsonrpc: "2.0", method: "call", id: 1, params: params}),
        })
        .then(function (r) { return r.json(); })
        .then(function (data) { cb(data.result); })
        .catch(function (e) { console.error(url, e); });
    }

    // ── Searchable select wrapper ───────────────────────────────────────────
    function makeSearchable(selectEl, placeholder) {
        if (!selectEl || selectEl.dataset.searchableInit) return;
        selectEl.dataset.searchableInit = "1";
        selectEl.style.display = "none";

        var wrap = document.createElement("div");
        wrap.className = "searchable-select";
        selectEl.parentNode.insertBefore(wrap, selectEl);
        wrap.appendChild(selectEl);

        var input = document.createElement("input");
        input.type = "text";
        input.className = "form-control";
        input.autocomplete = "off";
        input.placeholder = placeholder || "Type to search...";
        if (selectEl.classList.contains("is-invalid")) input.classList.add("is-invalid");
        wrap.insertBefore(input, selectEl);

        var dropdown = document.createElement("div");
        dropdown.className = "searchable-select-dropdown";
        wrap.appendChild(dropdown);

        function selectedText() {
            var opt = selectEl.options[selectEl.selectedIndex];
            return (opt && opt.value) ? opt.text : "";
        }

        function buildList(filterText) {
            dropdown.innerHTML = "";
            // Every typed word must appear somewhere in the option, in any order
            // (e.g. "kia 10768" or "sushil sales").
            var terms = (filterText || "").toLowerCase().split(/\s+/).filter(Boolean);
            var any = false;
            Array.prototype.forEach.call(selectEl.options, function (opt) {
                if (!opt.value) return;
                var text = opt.text.toLowerCase();
                if (terms.some(function (t) { return text.indexOf(t) === -1; })) return;
                any = true;
                var item = document.createElement("div");
                item.className = "searchable-select-item" + (opt.value === selectEl.value ? " active" : "");
                item.textContent = opt.text;
                item.addEventListener("mousedown", function (e) {
                    e.preventDefault();
                    selectEl.value = opt.value;
                    input.value = opt.text;
                    dropdown.style.display = "none";
                    selectEl.dispatchEvent(new Event("change"));
                });
                dropdown.appendChild(item);
            });
            if (!any) {
                var empty = document.createElement("div");
                empty.className = "searchable-select-empty text-muted";
                empty.textContent = "No results";
                dropdown.appendChild(empty);
            }
        }

        input.addEventListener("focus", function () {
            buildList("");
            dropdown.style.display = "block";
        });
        input.addEventListener("input", function () {
            buildList(input.value);
            dropdown.style.display = "block";
        });
        input.addEventListener("blur", function () {
            setTimeout(function () {
                dropdown.style.display = "none";
                input.value = selectedText();
            }, 150);
        });

        input.value = selectedText();

        // Exposed so callers can refresh the visible text after options are
        // repopulated via AJAX (e.g. location -> sublocation, location -> assets)
        selectEl._searchableRefresh = function () {
            input.value = selectedText();
        };
    }

    // ── Cascading location levels ───────────────────────────────────────
    var LEVEL_LABELS = ["Location", "Building / Area", "Room / Section"];
    var levelsEl = document.getElementById("location_levels");

    function levelLabel(i) { return LEVEL_LABELS[i] || ("Sub-area (level " + (i + 1) + ")"); }
    function levelSelect(i) { return document.getElementById("loc_level_" + i); }

    function leafLocationId() {
        var leaf = "";
        for (var i = 0; levelSelect(i); i++) {
            if (!levelSelect(i).value) break;
            leaf = levelSelect(i).value;
        }
        return leaf;
    }

    function syncHiddenLocation() {
        var top = levelSelect(0) ? levelSelect(0).value : "";
        var leaf = leafLocationId();
        document.getElementById("location_id").value = top || "";
        document.getElementById("sublocation_id").value = (leaf && leaf !== top) ? leaf : "";
    }

    function removeLevelsAfter(index) {
        Array.prototype.forEach.call(levelsEl.querySelectorAll("[data-level]"), function (col) {
            if (col.tagName !== "SELECT" && parseInt(col.dataset.level) > index) col.remove();
        });
    }

    function selectedText(sel) {
        var opt = sel.options[sel.selectedIndex];
        return opt && opt.value ? opt.text.trim() : "";
    }

    function addLevel(index, locs) {
        var parentName = selectedText(levelSelect(index - 1));
        var col = document.createElement("div");
        col.className = "col-md-4 mb-3";
        col.dataset.level = index;
        var label = document.createElement("label");
        label.className = "form-label fw-bold";
        label.htmlFor = "loc_level_" + index;
        label.textContent = levelLabel(index);
        var sel = document.createElement("select");
        sel.id = "loc_level_" + index;
        sel.className = "form-select loc-level";
        sel.dataset.level = index;
        var all = document.createElement("option");
        all.value = "";
        all.text = "— All of " + parentName + " —";
        sel.appendChild(all);
        locs.forEach(function (l) {
            var opt = document.createElement("option");
            opt.value = l.id;
            opt.text = l.name;
            opt.dataset.hasChildren = l.has_children ? "1" : "";
            sel.appendChild(opt);
        });
        col.appendChild(label);
        col.appendChild(sel);
        levelsEl.appendChild(col);
        sel.addEventListener("change", function () { onLevelChange(index); });
        makeSearchable(sel, "Search " + levelLabel(index).toLowerCase() + "...");
    }

    // opts.reloadAssets (default true), opts.then: callback once the next level is built
    function onLevelChange(index, opts) {
        opts = opts || {};
        removeLevelsAfter(index);
        syncHiddenLocation();
        var sel = levelSelect(index);
        var opt = sel.options[sel.selectedIndex];
        if (sel.value && opt && opt.dataset.hasChildren) {
            callJSON("/my/tickets/sublocations", {parent_id: parseInt(sel.value)}, function (locs) {
                if (locs && locs.length) addLevel(index + 1, locs);
                if (opts.then) opts.then();
            });
        } else if (opts.then) {
            opts.then();
        }
        if (opts.reloadAssets !== false) reloadAssets(leafLocationId(), null);
    }

    // Select a chain of location ids level by level, e.g. [WATTAYAH, FORD SHOWROOM, BOILER ROOM]
    function selectPath(pathIds, reloadAtEnd, done) {
        function step(i) {
            var sel = levelSelect(i);
            if (i >= pathIds.length || !sel) {
                syncHiddenLocation();
                if (reloadAtEnd) reloadAssets(leafLocationId(), null);
                if (done) done();
                return;
            }
            sel.value = String(pathIds[i]);
            if (sel.value !== String(pathIds[i])) sel.value = "";
            if (sel._searchableRefresh) sel._searchableRefresh();
            if (!sel.value) { step(pathIds.length); return; }
            onLevelChange(i, {reloadAssets: false, then: function () { step(i + 1); }});
        }
        step(0);
    }

    function reloadAssets(locationId, preserveAssetId) {
        var sel = document.getElementById("asset_id");
        var keep = preserveAssetId || sel.value;
        callJSON("/my/tickets/assets_by_location",
            {location_id: locationId ? parseInt(locationId) : null},
            function (assets) {
                sel.innerHTML = '<option value="">— Select Equipment —</option>';
                (assets || []).forEach(function (a) {
                    var opt = document.createElement("option");
                    opt.value = a.id;
                    opt.text = a.name;
                    opt.dataset.locationId   = a.location_id   || "";
                    opt.dataset.locationName = a.location_name || "";
                    opt.dataset.locationPath = a.location_path || "";
                    sel.appendChild(opt);
                });
                sel.value = keep || "";
                if (sel.value !== String(keep || "")) {
                    sel.value = "";
                    clearAssetLocation();
                }
                if (sel._searchableRefresh) sel._searchableRefresh();
            }
        );
    }

    // ── Asset change — fill in its location levels ───────────────────────
    function onAssetChange(assetId) {
        if (!assetId) { clearAssetLocation(); return; }
        var sel = document.getElementById("asset_id");
        var opt = sel.options[sel.selectedIndex];
        var path = (opt.dataset.locationPath || "").split(",").filter(Boolean);
        var name = opt.dataset.locationName || "";
        if (name) {
            document.getElementById("asset_location_display").textContent = name;
            document.getElementById("asset_location_row").style.display = "";
        } else {
            clearAssetLocation();
        }
        if (path.length) {
            // Picking the asset drives the location, not the other way round.
            selectPath(path, false);
        }
    }
    window.onAssetChange = onAssetChange;

    function clearAssetLocation() {
        document.getElementById("asset_location_display").textContent = "—";
        document.getElementById("asset_location_row").style.display = "none";
    }

    // ── Init on load ─────────────────────────────────────────────────────
    document.addEventListener("DOMContentLoaded", function () {
        var top = levelSelect(0);
        makeSearchable(top, "Search location...");
        top.addEventListener("change", function () { onLevelChange(0); });
        makeSearchable(document.getElementById("asset_id"), "Search equipment...");
        makeSearchable(document.getElementById("portal_approver_id"),
                       "Type name, emp code, department...");

        // Re-render after a validation error: restore the chosen levels.
        var initial = (levelsEl.dataset.initialPath || "").split(",").filter(Boolean);
        var assSel = document.getElementById("asset_id");
        if (initial.length) {
            selectPath(initial, true);
        } else if (assSel && assSel.value) {
            onAssetChange(assSel.value);
        }
    });
})();
//
